function stopRoomListeners(){[presenceUnsub,matchUnsub,ticUnsub,duoUnsub].forEach(fn=>{if(fn)fn()});presenceUnsub=matchUnsub=ticUnsub=duoUnsub=null;roomUserUid=null;roomMembers=[];roomPresence={};roomConnected=false;liveMatch=null;cloudTic=null;cloudDuo=null;cloudSpin=null}
async function connectRoomForUser(){if(!firebaseReady||!user||(roomUserUid===user.uid&&!roomError))return;if(presenceUnsub||matchUnsub||ticUnsub||duoUnsub)stopRoomListeners();roomError='';roomUserUid=user.uid;updateRoomUI();try{roomMembers=await getRoomMemberUids();if(!roomMembers.includes(user.uid))throw new Error('This account is not one of the two people invited to this room.');presenceUnsub=startRoomPresence(user.uid,(presence,connected)=>{if(presence)roomPresence=presence;if(connected!==undefined)roomConnected=connected;updateRoomUI()},err=>{console.error('Realtime Database presence error:',err);const code=String(err?.code||'unknown');const denied=/permission|denied/i.test(code+' '+String(err?.message||''));roomError=denied?'Realtime Database denied room access. Confirm rtdb-room-members.json was imported at the database root and database.rules.json is published in her-bright.':`Realtime Database presence failed (${code}). Check the configured database URL and connection.`;updateRoomUI()});matchUnsub=subscribeMatch(data=>{liveMatch=data;if(Number.isFinite(data?.spinPoints)){spinScore=data.spinPoints;$('#spinScore').textContent=spinScore;localStorage.setItem('bright-spin-score',spinScore)}updateRoomUI()},err=>{console.error(err);roomError='Could not read the match room. Check Firestore room rules.';updateRoomUI()});ticUnsub=subscribeTicBoard(data=>{cloudTic=data;if(currentPage==='games'&&game==='tic'&&ticMode==='online')renderGame()},err=>console.error(err));duoUnsub=subscribeDuoGame(data=>{cloudDuo=data;if(currentPage==='games'&&game===data?.game)renderGame()},err=>console.error(err));updateRoomUI()}catch(e){console.error(e);roomError=e.message||'Could not load your private room. Check setup.';updateRoomUI()}}
