function spin(category,challenge,turn=spinTurn,completed=false,targetUid=null,isCustom=false){const canComplete=!firebaseReady||!user||targetUid===user.uid;$('#spinStatus').textContent=completed?'Challenge complete · next turn is ready ♡':canComplete?`${turn} spun it · your turn to do the challenge ♡`:`${turn} spun it · waiting for ${displayPlayer(targetUid)} to complete it…`;$('#challengeBox').innerHTML=`<span class="challenge-category">${isCustom?'CUSTOM · ':''}${safe(category)}</span><p>${safe(challenge)}</p><button class="subtle-button" id="doneChallenge" ${(completed||!canComplete)?'disabled':''}>${completed?'Challenge complete ✓':canComplete?'Done! +1 point ♡':`Waiting for ${safe(displayPlayer(targetUid))}…`}</button>`;if(completed||!canComplete)return;$('#doneChallenge').onclick=()=>{const btn=$('#doneChallenge');if(firebaseReady&&user){if(targetUid!==user.uid)return toast('Your person needs to confirm their challenge.');btn.disabled=true;btn.textContent='Saving…';finishSpinChallenge(user.uid,roomMembers).then(changed=>{if(changed){spinScore++;localStorage.setItem('bright-spin-score',spinScore);$('#spinScore').textContent=spinScore}}).catch(e=>{btn.disabled=false;btn.textContent='Done! +1 point ♡';toast(e.message||'Could not update the shared challenge.')})}else{spinScore++;localStorage.setItem('bright-spin-score',spinScore);$('#spinScore').textContent=spinScore;$('#spinStatus').textContent=`Lovely! ${spinTurn} is up next ♡`;btn.disabled=true;btn.textContent='Challenge complete ✓'}};}
