$('#spinBtn').onclick=async()=>{
 if(!firebaseReady){go('room');toast('Spin It stays locked until both players connect.');return}
 if(!user||!roomMatchActive('spin')){go('room');toast('Match with your person in the Duo Room first.');return}
 if(liveMatch.turnUid!==user.uid){toast('It’s your person’s turn to spin ♡');return}
 const customText=$('#customChallengeInput').value.trim(),categorySelect=$('#customChallengeType');let cat,task;
 if(customText){cat=categorySelect.value==='TRUTH'?'TRUTH':'DARE';task=customText;if(task===lastChallenge||task===cloudSpin?.challenge){toast('That task was just used. Try a different one ♡');return}}
 else{const cats=['TRUTH','DARE'];let attempt=0;do{cat=cats[Math.floor(Math.random()*cats.length)];task=challenges[cat][Math.floor(Math.random()*challenges[cat].length)];attempt++}while((task===lastChallenge||task===cloudSpin?.challenge)&&attempt<30)}
 const spinner=displayPlayer(user.uid),nextUid=roomMembers.find(id=>id!==user.uid);spinTurn=displayPlayer(nextUid);
 const targetAngle=cat==='TRUTH'?270:90,wholeTurns=Math.ceil(spinRotation/360)*360+1080;spinRotation=wholeTurns+targetAngle+Math.floor(Math.random()*11)-5;$('#spinWheel').style.transform=`rotate(${spinRotation}deg)`;$('#spinBtn').disabled=true;
 setTimeout(async()=>{try{await commitSpin(user.uid,roomMembers,{category:cat,challenge:task,rotation:spinRotation,custom:!!customText});lastChallenge=task;if(customText){$('#customChallengeInput').value='';$('#customChallengeCount').textContent='0 / 180'}spin(cat,task,spinner,false,nextUid,!!customText);updateRoomUI()}catch(e){toast(e.message||'Could not sync the spin.');updateRoomUI()}},2300)
};$('#switchTurn').onclick=()=>{if(firebaseReady)return;spinTurn=spinTurn==='Bright'?'You':'Bright';$('#spinStatus').textContent=`It's ${spinTurn}'s turn ♡`;toast(`The turn is now ${spinTurn}'s.`)};
