function renderDiary(){const entries=JSON.parse(localStorage.getItem('bright-diary')||'[]');$('#diaryList').innerHTML=entries.slice(-3).reverse().map(e=>`<div class="diary-entry">${safe(e.text)}<small>${safe(e.date)}</small></div>`).join('')};renderDiary();$('#diarySave').onclick=()=>{const text=$('#diaryInput').value.trim();if(!text){toast('Write a little something first ♡');return}const entries=JSON.parse(localStorage.getItem('bright-diary')||'[]');entries.push({text,date:new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})});localStorage.setItem('bright-diary',JSON.stringify(entries));$('#diaryInput').value='';renderDiary();toast('A little memory, safely tucked away ♡')};
