let mediaRecorder=null,recordedChunks=[];$('#voiceBtn').onclick=async()=>{if(mediaRecorder?.state==='recording'){mediaRecorder.stop();$('#voiceBtn').textContent='Start recording ●';$('#voiceStatus').textContent='Finishing your voice note…';return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('#voiceStatus').textContent='Voice recording needs a modern browser and microphone permission.';return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});recordedChunks=[];mediaRecorder=new MediaRecorder(stream);mediaRecorder.ondataavailable=e=>{if(e.data.size)recordedChunks.push(e.data)};mediaRecorder.onstop=()=>{const audio=$('#voicePlayback');audio.src=URL.createObjectURL(new Blob(recordedChunks,{type:mediaRecorder.mimeType||'audio/webm'}));audio.classList.remove('hidden');$('#voiceStatus').textContent='Your voice note is ready to replay on this device. ♡';stream.getTracks().forEach(t=>t.stop())};mediaRecorder.start();$('#voiceBtn').textContent='Stop recording ■';$('#voiceStatus').textContent='Recording… say something lovely.'}catch(err){$('#voiceStatus').textContent=err.name==='NotAllowedError'?'Microphone permission was not granted. You can still leave a note in chat.':'Could not start recording in this browser.'}};
let foundHearts=JSON.parse(localStorage.getItem('bright-hearts')||'[]');function updateTreasure(){foundHearts.forEach(id=>{const b=$(`[data-hidden-heart="${id}"]`);if(b)b.classList.add('found')});$('#treasureStatus').textContent=foundHearts.length===3?'All 3 hearts found! You found the best treasure: us. ♡':`${foundHearts.length} of 3 found`};updateTreasure();$$('[data-hidden-heart]').forEach(b=>b.onclick=()=>{if(!foundHearts.includes(b.dataset.hiddenHeart)){foundHearts.push(b.dataset.hiddenHeart);localStorage.setItem('bright-hearts',JSON.stringify(foundHearts));updateTreasure();toast(foundHearts.length===3?'Treasure complete! You found all the love. ♡':'A hidden heart! Keep looking ♡')}});
